      "detail": "周武王姬发会庸、蜀、羌、髳、微、卢、彭、濮诸部东征，甲子日晨于商郊牧野击败商王帝辛（纣），商亡西周立。1976年临潼出土《利簋》铭文“武王征商，唯甲子朝，岁鼎，克昏夙有商”确证甲子日克商及木星（岁星）当空天象。然克商绝对公元年份历来众说纷纭，主要代表性学说有四：（1）前1046年1月20日说：《夏商周断代工程1996—2000年阶段成果报告》综合《利簋》岁鼎天象、《国语·周语下》伶州鸠述五星岁星天象、沣西琉璃河碳十四测年及金文历谱拟定；（2）前1045年说：倪德卫（David S. Nivison）、夏含夷（Edward L. Shaughnessy）据今本/古本《竹书纪年》与月食推算；（3）前1027年说：雷海宗、陈梦家等据《裴骃史记集解》引古本《竹书纪年》“自武王灭殷以至幽王凡二百五十七年”由前771年逆推；（4）前1122年说：西汉刘歆《三统历》推算（见《汉书·律历志》）。",
