      "detail": "赢姓非子居犬丘，善养马，周孝王召使主马于汧水、渭水之间，马大蕃息。孝王遂分土封非子为附庸，邑之于秦（今甘肃天水清水或张家川一带），使续嬴氏祀，号曰“秦嬴”，开启秦国立基关陇之始。",
