          "title": "申侯联缯与犬戎攻破镐京，杀周幽王于骊山下，西周灭亡",
          "detail": "周幽王废申后及太子宜臼，改立褒姒为后、褒姒子伯服为太子。申侯怒而联合缯国与西夷犬戎攻周（清华简《系年》载幽王先主动发兵围申，申联戎反击），破宗周镐京，杀周幽王与郑桓公于骊山之下，虏褒姒，尽取周室宝器而去，西周遂亡。诸侯立故太子宜臼（平王），虢公翰另立王子余臣于携（携王），形成二王并立局面。至于“烽火戏诸侯”一节见于《史记·周本纪》《吕氏春秋》，清华简《系年》未载，近代史学界多认为带有战国说部渲染或传说成分。",
          "category": "王朝更替",
          "regionId": "guanzhong",
          "source": "《史记·周本纪》《十二诸侯年表》；古本《竹书纪年》；清华大学藏战国竹简《系年》（第二章）",
