          "detail": "晋赵庄姬因赵婴齐被逐而向晋景公诬告赵同、赵括谋反，栾氏、郤氏为证。六月，晋讨杀赵同、赵括（下宫之难），赵庄姬子赵武从母畜于公宫；韩厥感念赵衰、赵盾两代勋劳，力劝景公“成季之勋，宣孟之忠，而无后，为善者其惧矣”，景公乃立赵武而反其田。（注：《史记·赵世家》另载屠岸贾灭赵、程婴公孙杵臼匿孤十五年复立，年代与人物同《左传》出入甚大，学界公认《左传》系实录而《史记》采战国传闻故事。）",
