          "detail": "楚惠王五十六年（前433年），姬姓曾国（随国）国君曾侯乙去世下葬于今湖北随州擂鼓墩一号墓，楚惠王熊章特铸镈钟相赠（铭“唯王五十六祀，返自西阳，楚王酓章作曾侯乙宗彝”）。1978年发掘出土完整青铜编钟六十五件，每钟可发双音，总音域跨五个半八度且十二律齐备，钟架铸刻各国律名对照长铭；同墓出土绘有青龙白虎与“斗”字及二十八宿名称的漆衣箱，为战国礼乐与天文学提供确凿纪年实物。",
