          "detail": "魏文侯尊礼子夏、田子方、段干木，任用李悝为相推行战国最早的系统变法：经济上行“尽地力之教”鼓励精耕间作，创“平籴法”丰年官购余粮、荒年平价抛售以稳农商；法制上博采列国刑典编成《法经》六篇（盗法、贼法、网法、捕法、杂法、具法），成为商鞅秦律与汉律之蓝本。同时任西门豹为邺令，严惩借“河伯娶妇”敛财之豪强巫祝，征民开凿漳水十二渠灌溉盐碱地，魏国遂率先强盛（变法具体年份传世无单一年份，学界通系于文侯中前期约前422年前后）。",
