          "detail": "秦孝公十二年，于渭河北岸咸阳修筑冀阙宫廷，自栎阳正式迁都咸阳。大良造卫鞅推进第二次深化变法：（1）并诸小乡聚为大县，全国划设三十一县（《六国年表》作四十一县），每县置县令、县丞，由国君直接任免；（2）“为田开阡陌封疆”，彻底铲除井田沟洫封疆限制，允许土地自由开垦与合法赋税登记，“赋税平”；（3）颁行国家标准度量衡器（传世秦孝公十八年即前344年《商鞅方升》刻铭“爰积十六尊五分尊之一为升”即其实物铁证）；（4）强制拆分大家庭（民父子兄弟同室内息者为禁），养成小农耕战社会结构。",
