          "detail": "魏惠王发大军攻韩，韩向齐告急。齐军再次由田忌、田婴率领、孙膑任军师直捣大梁，魏将庞涓去韩回师追击。孙膑因势利导，令齐军入魏境首日筑十万灶，次日减为五万灶，三日减为三万灶；庞涓以为齐卒逃亡过半，遂丢下重步兵仅率轻车锐骑昼夜兼程追入马陵险狭谷道。孙膑预判其日暮必抵马陵，削大树白皮书“庞涓死于此树之下”，埋伏善射万弩手夹道待火齐发；庞涓夜至举火读字，齐弩万箭俱发，魏军大乱自相蹂躏，庞涓愤叹“遂成竖子之名”自刭（一说战死），齐军乘胜全歼魏主力并俘魏太子申，魏国从此丧失中原霸主地位。",
