          "detail": "秦武安君白起攻占韩国太行咽喉野王城，上党郡与韩都新郑通路断绝。韩桓惠王恐而命上党郡守冯亭献地于秦求和；冯亭与吏民不愿降秦，遂携上党十七城户籍地图归附赵国以促韩赵合兵抗秦。赵孝成王不听平阳君赵豹“无功受祸”之谏，纳平原君赵胜贪利之议受上党地、封冯亭为华阳君，秦随即兴重兵与赵争夺上党。",
