          "detail": "秦将王龁攻上党，赵老将廉颇军于长平筑垒坚守三年不出。秦相范雎遣人持千金入赵行反间，扬言“秦之所恶，独畏马服子赵奢之子赵括为将耳！廉颇易与且降矣”。赵孝成王不听蔺相如与赵括生母力谏，果以徒读父书、不谙变通之赵括代廉颇；秦则秘密拜白起为上将军并下令泄者斩。赵括到军悉改军令出击，白起佯败诱其深入，遣奇兵二万五千绝赵军后路，又以五千骑截赵军大营与前锋为二，秦昭襄王更亲赴河内发十五岁以上男丁尽遮绝赵救兵及粮饷。至九月赵军断粮四十六日，士卒阴相杀食，赵括率锐卒搏战突围被秦军射杀，四十万赵军降秦；白起以赵卒反覆恐生乱，挟诈仅留年少者二百四十人归赵，余四十万降卒尽坑杀之，长平前后斩坑赵军共四十五万，赵国上下子哭其父、父哭其子，自此山东列国再无能单独与秦争锋之军事力量。",
