          "detail": "秦二世胡亥即位后诛戮诸公子大臣、复作阿房宫、尽征材士卫咸阳，赋敛益重。七月，阳城雇农陈胜与阳夏人吴广以屯长押解九百闾左贫民往戍渔阳，行至蕲县大泽乡遇暴雨道不通，度已失期，按秦律失期皆斩（注：睡虎地秦简《徭律》载暴雨失期可免罪，学界探讨或为秦二世严酷督责新令、或为陈吴激励戍卒之辞）。二人遂杀押解秦尉揭竿而起，陈胜高呼“王侯将相宁有种乎”，诈称公子扶苏、楚将项燕，袒右称大楚，连克蕲、铚、陈县，入据陈城称王定国号“张楚”。山东苦秦郡县望风响应：九月沛县泗水亭长刘邦于芒砀斩蛇起兵称沛公；会稽项梁、项羽叔侄杀郡守殷通，率八千江东子弟渡江北上；武臣、田儋、韩广等亦相继自立，中国历史上第一次全国规模农民大起义席卷天下。",
