          "detail": "刘邦入咸阳封闭秦宫室府库还军灞上，召诸县父老豪杰宣布“约法三章”：“杀人者死，伤人及盗抵罪，余悉除去秦法”，秦人大喜。项羽坑杀章邯二十万秦降卒于新安后，统四十万大军破函谷关屯新丰鸿门；刘邦仅携百余骑赴“鸿门宴”卑辞谢罪，范增令项庄舞剑欲击沛公，赖项伯翼蔽、张良召樊哙带剑拥盾闯帐切责，刘邦借如厕间道脱险。项羽遂入咸阳杀子婴、火烧秦宫室三月不灭，阳尊楚怀王为义帝（旋密令弑于江中），自称“西楚霸王”都彭城，分封十八诸侯王，把关中三分为雍（章邯）、塞（司马欣）、翟（董翳）三秦以堵截改封巴蜀汉中之汉王刘邦。刘邦入汉中烧绝栈道示无东意，旋采丞相萧何月下追回拜为大将之韩信“汉中对”方略，八月明修栈道掩护、主力自故道“暗度陈仓”奇袭破章邯，迅速收复关中三秦之地，拉开四年楚汉战争大幕。",
