          "detail": "韩信以木罂渡河虏魏王豹、破代兵后，与张耳率数万新募兵东下井陉击赵。赵王歇与成安君陈余号称二十万大军扼井陉口，陈余迂腐自诩义兵，拒纳广武君李左车三万奇兵绝汉粮道之毒计。韩信大喜，夜选二千轻骑人持一面汉军红旗从间道伏于赵营旁山，主力半夜出井陉口渡绵蔓水列“背水阵”（兵法所谓“陷之死地而后生，置之亡地而后存”）。天明赵军倾巢出营猛攻，汉军退无可退殊死血战，佯弃旗鼓走水上军；赵军果空壁争汉旗鼓，二千汉伏骑疾驰入赵空营尽拔赵旗立汉赤帜二千面，赵军攻汉不克回望本营皆汉赤帜，大惊溃散，韩信夹击斩陈余于泜水上、禽赵王歇，礼师李左车，不血刃而燕从风降附。同年荥阳前线刘邦纳陈平黄金四万斤行反间计，项羽果疑亚父范增，范增怒乞骸骨归至彭城疽发背死。",
