          "detail": "韩信袭破齐历下军入临淄，项羽急派大将龙且率号称二十万军救齐。韩信与龙且夹潍水列阵，夜令万余囊盛沙壅塞上游，旦日渡水击龙且佯败走还；龙且喜谓韩信怯而半渡追击，韩信令人决开沙囊，大水奔泻截断楚军大半不得渡，韩信急击杀龙且，尽定齐地受封齐王，拒绝武涉、蒯通“三分天下鼎足而居”之劝。同时彭越屡断楚军梁地粮草，项羽兵疲食尽，遂与刘邦订立“鸿沟之约”：鸿沟以西为汉，鸿沟以东为楚。九月项羽归汉王父母妻子引兵东归，刘邦即听张良、陈平“养虎自遗患”之谏毁约追击。",
