          "title": "垓下之战：韩信十面合围“四面楚歌”，项羽霸王别姬突围至乌江自刎",
          "detail": "汉五年冬十二月，刘邦以重封调集齐王韩信三十万主力、梁相国彭越、九江王英布、刘贾诸路大军共约六十万，将项羽十万楚军层层围困于垓下（今安徽灵璧东南）。韩信亲居中军先退诱敌、左右翼合击再乘胜反扑，大破楚军；入夜汉军四面皆唱楚歌，项羽惊叹“汉皆已得楚乎？是何楚人之多也”，于帐中对虞姬悲歌“力拔山兮气盖世，时不利兮骓不逝”，率八百壮骑乘夜溃围南出。渡淮迷道仅剩二十八骑，于东城再斩汉一将一都尉证“非战之罪”，退至乌江亭，亭长舣船劝渡江东再起，项羽笑曰“纵江东父兄怜而王我，我何面目见之”，赐乌骓马予亭长，步战杀汉军数百人后挥剑自刎，年三十一，楚汉之争终结。",
