          "detail": "二月甲午，诸侯王将相共尊汉王刘邦于山东定陶汜水之阳即皇帝位，国号仍为“汉”（史称西汉），立吕雉为皇后、刘盈为皇太子，五月兵皆罢归家，诏民前聚保山泽不书名数者各归其县复故爵田宅。高祖初欲长都洛阳，齐人戍卒娄敬（赐姓刘）求见力陈：周积德累善而都洛阳，今陛下取天下异于周，而秦地被山带河四塞以为固，卒然有急百万之众可具，“夫与人斗，不扼其吭、拊其背，未能全胜也”；留侯张良亦盛赞关中“沃野千里，天府之国”，高祖即日拍板驾西入关，暂驻栎阳并由萧何营建长安宫室。",
