          "detail": "秦末楚汉之际，匈奴冒顿单于（前209年鸣镝射杀父头曼自立）东灭东胡、西击走月氏、南并楼烦白羊河南王、北服浑庾丁零，控弦之士三十余万，建成草原首个强大游牧帝国。韩王信在马邑遭围叛降匈奴，高祖刘邦亲率三十二万大军迎击，冒严寒士卒堕指者什二三。冒顿匿精壮、示老弱诱敌，刘邦不听娄敬劝谏率轻兵先抵平城（今山西大同东北），竟遭冒顿四十万精骑按白、青、黑、赤四色马阵合围于白登山七日七夜，汉军内外断绝食水；高祖用陈平秘计派使间行重赂单于阏氏，冒顿乃开围一角放汉军突围。经此重挫，汉廷深知初定凋敝无力远征，遂于前198年正式采娄敬建议，以家人子名公主嫁单于为阏氏，岁奉絮缯酒米食物、结兄弟和亲之约；同年二月萧何督建壮丽未央宫落成，高祖自栎阳正式迁入长安视朝，叔孙通亦为汉定朝仪。",
