          "detail": "高祖刘邦与吕后疑忌手握重兵之异姓诸侯王：正月吕后用萧何计诱淮阴侯韩信入长乐宫钟室斩之夷三族（“成也萧何，败也萧何”）；三月废梁王彭越后复借吕后议诛之醢其肉赐诸侯；七月淮南王英布恐惧起兵反汉，高祖抱病亲征击破之。除偏远柔顺之长沙王吴芮外，汉初七大异姓王悉数铲除，高祖改封刘氏同姓九王跨州连郡拱卫中央，刑白马盟誓“非刘氏而王者，天下共击之”，正式形成西汉前期中央十五郡与东方同姓诸侯王国并立之“郡国并行制”，并颁《求贤诏》、由萧何据秦法增《户》《兴》《厩》三篇定《汉律九章》。同年五月高祖遣太中大夫陆贾出使岭南，赐赵佗南越王印绶，赵佗去黄屋左纛向汉称臣，陆贾归献总结秦失天下教训之《新语》十二篇。",
