          "title": "周勃、陈平联合刘氏宗室“诛诸吕”，迎立代王刘恒为汉文帝，开创“文景之治”",
          "detail": "七月辛巳吕太后病崩，遗诏以侄赵王吕禄为上将军统北军、吕王吕产为相国统南军，诸吕密谋作乱。齐哀王刘襄率先自山东起兵讨吕，长安城内太尉周勃、右丞相陈平与朱虚侯刘章里应外合，劫郦商令其子郦寄说吕禄解将印，周勃得襄平侯纪通授节驰入北军下令：“为吕氏右袒，为刘氏左袒！”军中皆左袒归刘。刘章率卒入未央宫击杀吕产，遂悉捕斩吕禄、吕媭等诸吕男女无少长皆斩。功臣元老集团忌惮齐王母家驷钧恶戾，共议高祖现存诸子以代王刘恒最为仁孝宽厚且母薄氏谨良，迎代王自晋阳入长安即皇帝位（汉文帝）。文帝在位二十三年宫室苑囿车骑服御无所增益，专务以德化民，与子景帝共同开创中国封建时代首个盛世“文景之治”。",
