          "title": "缇萦上书救父，汉文帝下诏废除肉刑；同年免除全国农业田租长达十余年",
          "detail": "齐太仓令淳于意（仓公）有罪当受肉刑，诏狱逮系长安。淳于意无男，小女缇萦随父西行上书阙下：“死者不可复生，刑者不可复属，虽复欲改过自新，其道无由也。妾愿没入为官婢，以赎父刑罪，使得自新。”文帝悲怜其孝意，五月正式下诏废除沿袭夏商周秦两千余年之黥（刺面）、劓（割鼻）、斩左右趾等残酷肉刑，改定律令以髡钳城旦舂与笞刑代替（其后景帝再两减笞数防笞死），标志中国古代刑罚体系由肉刑向徒刑的历史性转型。同年六月文帝下诏“其除田之租税”，此后直至文帝崩（连续十一年）全国免收农业土地税，府库充溢、贯朽粟陈。",
