          "detail": "冬匈奴三万骑入上郡、三万骑入云中，烽火直达甘泉、长安。汉廷发三将军备胡：刘礼军霸上、徐厉军棘门、河内守周亚夫军细柳（今陕西咸阳西南）。文帝亲往劳军，至霸上及棘门直驰出入；独至细柳营士卒披甲锐兵刃持满，天子先驱以无将军令被拒，文帝使使持节诏将军，亚夫乃传令开壁门，壁门士吏诫天子车骑“将军约，军中不得驱驰”，文帝按辔徐行，亚夫持兵揖曰“介胄之士不拜，请以军礼见”。出营后群臣皆惊，文帝叹曰：“嗟乎，此真将军矣！曩者霸上、棘门军，若儿戏耳！”月余匈奴退去，拜亚夫为中尉。",
