          "title": "司马迁、邓平、落下闳造《太初历》，定夏正寅月为岁首（春节正月初一定型）并把二十四节气纳入历法",
          "detail": "太初元年夏五月，汉武帝采太史令司马迁、公孙卿、壶遂建议，召集民间天文学家巴郡落下闳、邓平及唐都等二十余人改定新历。落下闳制浑仪实测星度，邓平定八十一分律历法，经与十余家历法实测校验弦望皆最精密，武帝遂颁行《太初历》：（1）废除秦及汉初以冬十月为岁首之颛顼历，正式改以夏历正月（建寅之月）为每年岁首，奠定此后两千余年中华民族农历正月初一过新年的传统；（2）首次将二十四节气准确写入官方历法指导农事，确立以“无中气之月置闰”的科学闰周；（3）依五德终始说定汉为土德，色尚黄、数用五，改定官名。同年太史令司马迁遵亡父司马谈遗命，正式执笔撰述《太史公书》（《史记》）。",
