          "detail": "天汉二年贰师将军李广利出酒泉击右贤王，李广之孙骑都尉李陵自请率荆楚勇士步卒五千教射者出居延以分胡兵。李陵北行三十日至浚稽山与单于主力三万骑（继召左右地兵八万余骑）遭遇，以连弩千张、大车为营边战边退八日，杀伤匈奴万余人，距居延百余里鞮汗山一日射尽五十万矢、徒手持尺刀白刃搏战，夜突围被俘降匈奴。长安群臣皆媒孽其短，唯太史令司马迁痛惜李陵平生奇士、提步卒不满五千深践戎马之地抑数万之师，于武帝前盛言陵功以宽帝心；武帝疑迁为陵游说而沮贰师，下迁腐刑狱（前98受宫刑）。司马迁忍受奇耻大辱出任中书令，以“文王拘而演《周易》，仲尼厄而作《春秋》”自励，约于征和二年（前91）前后写成中国第一部纪传体通史《太史公书》（《史记》，十二本纪、十表、八书、三十世家、七十列传共百三十篇），“究天人之际，通古今之变，成一家之言”，被鲁迅誉为“史家之绝唱，无韵之《离骚》”。",
