          "detail": "汉武帝暮年驻甘泉宫多病，疑左右人为巫蛊诅咒。与卫皇后及皇太子刘据素有嫌隙之绣衣直指使者江充，借治蛊之机指使胡巫在太子宫掘出桐木偶人诬太子大逆。七月壬午，太子刘据派使赴甘泉自明不得通，情急纳少傅石德策矫制捕斩江充，发长乐宫卫卒与丞相刘屈氂所统北军在长安城中血战五日，死者数万人、流血入沟。武帝自甘泉震怒还京闭城平乱，皇后卫子夫缴玺绶自杀，太子兵败东逃湖县泉鸠里民家，八月辛亥被围自经身亡，三男一女遇害，唯襁褓皇曾孙刘病已赖邴吉拼死护全（前89田千秋讼太子冤，武帝悔悟族灭江充、烧苏文，作思子宫与归来望思之台）。",
