          "title": "汉武帝颁《轮台罪己诏》罢边功归于务农，搜粟都尉赵过推广“代田法”与耦犁耧车",
          "detail": "征和四年（先一年贰师将军李广利兵败燕然山降匈奴），桑弘羊等奏请增派戍卒远赴西域轮台以东开垦五千顷并筑亭障。晚年汉武帝痛定思痛，下达著名的《轮台诏》，断然否决轮台屯田议，公开向天下罪己：“朕即位以来，所为狂悖，使天下愁苦，不可追悔。自今事有伤害百姓、糜费天下者，悉罢之！”声明“当今务在禁苛暴，止擅赋，力本农，修马复令”。遂封丞相田千秋为“富民侯”以明休息思富养民之意，并擢升赵过为搜粟都尉，在三辅、河东、弘农及边郡驻军大力推广沟垄轮换抗旱保墒之“代田法”，改良创制二牛三人“耦犁”与一日可播一顷之三脚条播“耧车”，用力少而得谷多，使几近崩溃的西汉民生得以迅速挽救。",
