          "title": "长安召开“盐铁会议”廷辩国策，罢酒榷官；苏武持节自匈奴荣归长安",
          "detail": "始元六年春二月，汉昭帝与霍光诏有司问郡国所举贤良、文学之士六十余人“民所疾苦”。在长安朝堂上，代表民间儒生与地方利益的贤良文学与代表国家干预财政的御史大夫桑弘羊展开中国古代经济政治思想史上最著名的“盐铁大论战”（宣帝时汝南桓宽据此整理成《盐铁论》六十篇）：围绕盐铁官营、酒类专卖（榷酤）、均输平准是“富国强边、抑兼并”还是“与民争利、伤农败俗”，以及对匈奴当主战抑或主和修德反复交锋；七月朝廷折中下诏罢除酒类专卖官（榷酤官），保留盐铁官营。同年汉匈恢复和亲，匈奴前诡称苏武已死，常惠夜教汉使责单于“天子射上林中得雁，足有系帛书言武等在某泽中”，单于惊谢，终放还留胡十九年、须发尽白的苏武等九人归长安，拜苏武为典属国。",
          "category": "思想与文化",
          "regionId": "guanzhong",
