          "detail": "元平元年四月癸未，二十一岁的汉昭帝无嗣病崩。霍光迎立武帝孙昌邑王刘贺入承大统；刘贺即位仅二十七日，即与昌邑旧臣纵欲无度、不遵大行丧礼并图谋排挤辅政旧臣。六月癸巳，霍光与车骑将军张安世、大司农田延年集朝臣议，奏请年仅十五岁的上官皇太后驾临未央宫承明殿，历数刘贺二十七日间行淫乱千一百二十七事，当殿废黜刘贺遣归故国汤沐邑二千户（宣帝元康三年封为豫章海昏侯；2011—2016年江西南昌新建区发掘刘贺海昏侯大墓，出土金饼马蹄金478件、铜钱十余吨、孔子徒人图漆衣镜及失传《齐论语》竹简等万余件珍贵文物）。七月庚申，霍光从邴吉奏，迎立在民间长大、熟知闾里奸邪与吏治得失之十八岁戾太子孙刘病已（后改名询）即位，是为汉宣帝。",
