          "detail": "匈奴壶衍鞮单于连攻乌孙取车延恶师地，乌孙昆弥翁归靡与解忧公主上书愿发国半精兵五万骑与汉合讨匈奴。本始三年正月，汉宣帝命祁连将军田广明、蒲类将军赵充国、虎牙将军田顺、度辽将军范明友、前将军韩增五路共十五万余骑分道出塞二千余里，同时拜校尉常惠持节护乌孙兵西线出击。匈奴闻汉大军出畏怖远遁，东线斩获较少，而西线常惠督乌孙昆弥五万骑直捣匈奴右谷蠡王庭，大获全胜，俘单于父行及嫂居次、名王犁污都尉千长骑将以下三万九千余人，获马牛羊驴橐驼七十余万头；同冬匈奴复遭罕见暴雪，人民畜产冻死什九，丁令乘北、乌桓击东、乌孙击西，匈奴彻底丧失草原霸权。",
