          "detail": "神爵元年先零羌与诸羌解仇结盟攻金城郡，逾七十岁的后将军赵充国自请“百闻不如一见，臣愿驰至金城图上方略”。充国渡湟水瓦解羌人部族联盟后，拒绝朝廷催促急战侥幸之诏，在湟中上呈千古名篇《屯田奏》，详列罢骑兵、留步兵万零二百八十一人分屯临羌至浩亹务农困敌之“十二便”，指出“以逸待劳，兵之利；内有亡费之利，外有守御之备”。宣帝力排众议批准屯田，至次年五月先零羌果内溃斩杨玉降汉，不烦大军血战而河湟平定，置金城属国，奠定中国历代西北军屯固边制度圭臬。",
