          "detail": "神爵二年秋，匈奴握衍朐鞮单于暴虐引起内乱，掌管西域赋税（童仆都尉）之左地贵人日逐王先贤掸率万二千骑诣驻渠犁之汉卫司马郑吉投降。郑吉发渠犁、龟兹诸国兵五万人迎日逐王护送长安封归德侯，匈奴在西域统治彻底瓦解。因郑吉此前攻破车师打通北道、今又迎降日逐威服南道，汉宣帝遂正式创设中央派驻西域最高军政长官“西域都护”（秩比二千石），命郑吉为首任都护，并护天山南北两道三十六国（后析为五十余国），督察乌孙、康居诸外国动静，都护府治所设于西域地理中心乌垒城（今新疆巴音郭楞州轮台县策大雅东北），标志新疆天山南北正式纳入中国中央政府行政管辖体系。",
