          "detail": "甘露三年春正月，南下称臣之匈奴呼韩邪单于亲赴长安朝见汉宣帝。宣帝于甘泉宫盛礼接见，特诏待以客礼、位在诸侯王之上，赞谒称臣而不名，厚赐冠带衣裳、黄金玺盭绶、玉具剑、安车鞍马、锦绣缯絮，留月余遣归居漠南光禄塞下，汉匈百年大战终结。宣帝美四夷宾服、追思辅佐武功大臣，命于未央宫麒麟阁图画大司马霍光、张安世、韩增、赵充国、魏相、丙吉、杜延年、刘德、梁丘贺、萧望之、典属国苏武共十一人形貌署其官爵姓名，开启中国帝王图像褒功传统。",
