          "detail": "河平三年秋八月，汉成帝以中秘书颇散亡，遣谒者陈农遍求遗书于天下，诏光禄大夫刘向校勘经传、诸子、诗赋，步兵校尉任宏校兵书，太史令尹咸校数术，侍医李柱国校方技。刘向对公私善本（含孔壁古文简、汲冢类竹书）逐篇比勘脱误、编定目次，每校定一书即撰解题叙录奏上，汇为《别录》二十卷（《战国策》《列女传》《说苑》《新序》等皆经其编定传世）。刘向卒后汉哀帝命其子刘歆卒父业，刘歆总括群书万三千余卷撰成中国第一部官修分类图书总目《七略》（班固据此删润为《汉书·艺文志》），先秦两汉学术源流赖此得以系统保存。",
          "category": "思想与文化",
          "regionId": "guanzhong",
