          "detail": "绥和元年夏四月，采大司空何武议，改秦汉以来副丞相性质之御史大夫为大司空，禄比丞相，与大司马、丞相（哀帝元寿二年改称大司徒）鼎足分掌行政、军事、监察水土，两汉三公体制转型定型。冬十一月曲阳侯王根病免，举荐恭俭折节、散财赡士而声誉冠于诸父之三十八岁侄新都侯王莽自代，王莽遂初登大司马辅政高位。",
