          "title": "汉成帝崩哀帝立；师丹、孔光奏行“限田限奴婢”抑兼并方案遭外戚宠臣阻挠流产",
          "detail": "三月汉成帝暴崩，四月定陶王刘欣入继大统（汉哀帝）。针对西汉晚期豪强地主“富者田连阡陌，贫者亡立锥之地”、流民卖妻鬻子之深重社会危机，大司空师丹建议限民名田，丞相孔光、大司空何武奏定具体条格：诸侯王、列侯、公主至吏民占有土地（名田）最高皆不得逾三十顷，蓄养私属奴婢自诸侯王二百人依次递减至吏民三十人，期三年，过限者没入官。消息传出田宅奴婢市价大落，然哀帝母家外戚丁氏、傅氏及男宠董贤正大肆敛聚田宅，百般掣肘，哀帝遂批“且须后”（暂缓施行），中国帝制时代首次官方法定限田尝试宣告夭折。",
          "category": "政治与制度",
