          "title": "王莽即真天子位建立“新朝”，托古改制颁“王田私属”禁买卖令并废五铢钱",
          "detail": "始建国元年春正月朔，王莽按赤帝传黄帝金策符命正式即真天子位，定有天下之国号曰“新”，改正朔、易服色尚黄，以汉定安公刘婴（孺子婴）奉汉祀。夏四月王莽托《周礼》复古大举改制：（1）下令“更名天下田曰王田，奴婢曰私属，皆不得买卖；其男口不盈八而田过一井（九百亩）者，分余田予九族邻里乡党，故无田今当受田者如制度”，敢非议井田圣制者投诸四裔；（2）废除信誉卓著之西汉五铢钱，禁民挟铜炭，推行虚值大钱（大泉五十、契刀、错刀，次年更扩为五物六名二十八品“宝货制”）；（3）频繁改易天下官名与郡县地名（岁复变更，吏民不能纪）。结果豪强小民俱困，农商失业、食货俱废，百姓涕泣于市道，坐买卖田宅奴婢铸钱抵罪自诸侯卿大夫至庶民不可胜数。",
