          "title": "昆阳之战：刘秀率数千敢死士冲阵斩帅，一举击溃王莽四十二万主力大军",
          "detail": "二月辛巳绿林诸将拥立软弱宗室刘玄为更始帝（旋攻克宛城并忌杀威望日隆之大司徒刘縯）。王莽震恐，倾尽天下精兵四十二万（号称百万），命大司徒王寻、大司空王邑率六十三家兵法将领并巨无霸驱虎豹犀象南下，五月合围仅有八九千汉兵驻守之昆阳小城（今河南叶县），钲鼓之声闻数十里，矢下如雨。太常偏将军刘秀夜间与李轶等十三骑突出城南，驰赴郾、定陵悉发诸营援军数千人回救：六月己卯刘秀亲率步骑千余为前锋距莽阵四五里斩首数千级，再选敢死士三千人自城西水渡直扑王寻、王邑中坚大营！王邑轻敌禁诸营妄动独战，阵乱被乘，汉军杀王寻，昆阳城中守军亦鼓噪杀出内外夹击；适狂风暴雨雷电交加，屋瓦皆飞、虎豹股战，莽四十二万大军土崩瓦解自相践踏伏尸百余里，溺死滍水者以万数水为不流，尽获其军实辎重，新莽军事脊梁一日折断。",
