          "detail": "昆阳惨败后海内豪杰蜂起响应，析人邓晔、于匡起兵开武关迎更始大军（申屠建、李松）西入关中。九月戊申三辅义兵与更始军攻入长安，城中少年朱弟、张鱼等呼噪焚烧未央宫室；王莽衣纯紫衣佩玺持虞帝匕首随斗柄旋坐以厌胜，十月戊申退保沧池渐台，众兵围台矢尽搏战，商人杜吴杀王莽，校尉公宾就斩莽首悬于宛市（百姓争切食其舌），历时十五年的新朝覆亡。",
