          "title": "汉光武帝刘秀于河北鄗南即皇帝位建立东汉，改元建武，定都洛阳",
          "detail": "刘秀以破虏将军行大司马事持节北渡黄河徇河北，除王莽苛政、释放囚徒，历经真定结亲郭氏得河北豪族支持，攻拔邯郸诛卜者假子昌城王郎，又击破并轻骑按行收编铜马、高湖、重连等河北农民军数十万众（降者相语“萧王推赤心置人腹中，安得不投死乎”，遂号“铜马帝”）。建武元年六月己未（25年8月5日），刘秀顺应诸将冯异、耿纯、铫期等劝进，于河北鄗县南千秋亭五成陌设坛即皇帝位，延续“汉”国号（史称东汉/后汉），大赦天下，改元建武。九月赤眉军攻破长安杀更始帝刘玄；十月癸丑光武帝车驾入洛阳幸南宫，遂定都洛阳（建武三年即27年正月冯异于崤底大破赤眉，光武帝于宜阳受刘盆子、樊崇十余万赤眉军缴传国玉玺投降）。",
