          "detail": "建武十五年六月，针对东汉开国豪强世族大肆隐匿田产与依附丁口（“州郡检核垦田顷亩及户口年纪，又考实二千石长吏阿枉不平者”），光武帝下诏全国推行“度田”。然刺史太守多畏避贵戚豪姓（河南尹及帝乡南阳尤甚，“多近水泽膏腴之田，不得度实”），反将赋役转嫁逼迫贫弱小民，致青、徐、幽、冀豪强煽动郡兵妖贼群起骚乱；次年秋九月光武帝雷厉风行将度田不实之河南尹张伋及诸郡太守十余人全部下狱处死，牛马归田平息骚动，然豪族大庄园经济仍成为东汉社会根深蒂固之结构底色。",
