          "detail": "建武十六年交趾郡麊冷县雒将之女征侧（嫁朱鸢人诗索）与妹征贰起兵反叛，九真、日南、合浦蛮俚响应，略六十五城自立为王。建武十八年光武帝拜年过六旬之马援为伏波将军、扶乐侯刘隆为副，率万余军沿海岸辟道千余里南进，会师浪泊（今越南河内西湖一带）大破叛军；建武十九年正月斩征侧、征贰传首洛阳，冬乘胜追讨九真余部至居风降服全境（传说立铜柱表汉极界）。马援所过辄为郡县治城郭、穿灌溉水渠以利民，奏省繁县并条奏越律与汉律相驳者十余事与越人申明旧制，岭南交州遂安。",
