          "detail": "匈奴连岁旱蝗赤地千里，草木尽枯，人畜饥疫死耗太半。呼韩邪单于之孙右薁鞬日逐王比（领南边八部）遭蒲奴单于猜忌欲诛，建武二十四年春献匈奴地图诣西河求内附；冬十月八部大人共立比为呼韩邪单于（袭用祖父尊号以修汉好），款五原塞愿永为汉藩蔽捍御北虏。光武帝力采五官中郎将耿国议准许内附，建武二十六年（50年）正式设“使匈奴中郎将”率弛刑徒卫护南单于居西河美稷（今内蒙古准格尔旗西北），岁赐缯絮米糒，南匈奴八部分屯北地、朔方、五原、云中、定襄、雁门、代郡塞内，而蒲奴单于所部成为北匈奴退居漠北，胡汉杂居河套并州由此绵延近三百年。",
