          "detail": "建武中元二年春正月，日本列岛九州北部弥生时代古国“倭奴国”（今福冈博多一带之奴国）遣使者跨海奉贡朝贺洛阳，使人自称大夫，系倭国之极南界；光武帝赐以蛇纽纯金印绶。清乾隆四十九年（日本天明四年，1784年），日本筑前国那珂郡志贺岛（今福冈市东区志贺岛）农民掘沟时出土这枚边长2.3厘米、重108.7克之纯金蛇纽印，印面阴刻汉篆“汉委奴国王”五字，与《后汉书》文献记载毫厘不爽，成为东亚汉文化圈册封朝贡体制与中日信史开端之无上实物铁证。",
