          "detail": "永平八年汉明帝诏令天下死罪皆入缣赎，异母弟楚王刘英遣郎中令奉黄缣白纨三十匹诣国相赎罪；明帝下诏报还缣纨以助伊蒲塞（优婆塞，在家男居士）、桑门（沙门，出家僧人）之盛馔，诏文明言“楚王诵黄老之微言，尚浮屠之仁祠，洁斋三月，与神为誓”。此诏乃中国正史本纪列传关于皇室与长江淮泗地区佛道并祀及梵僧居士活动之最早确切信史记载。",
