          "title": "汉明帝“永平求法”遣使天竺与建洛阳白马寺说（年代与细节存后世追述附会）",
          "detail": "《后汉书·西域传》载世传汉明帝夜梦金人长大、顶有光明，以问群臣，或曰西方有神名曰佛，明帝遂遣使天竺问佛道法，遂于中国图画形象；后世佛典（《四十二章经序》、东晋袁宏《后汉纪》、南朝梁慧皎《高僧传》）进一步系于永平十年（67年），称郎中蔡愔、秦景等于大月氏遇天竺沙门摄摩腾、竺法兰以白马驮经像同还洛阳，敕于城西雍门外建白马寺译《四十二章经》。现代史学界（汤用彤等）考证认为永平年间汉使通西域闻佛法确有历史背景，而具体年份、白马驮经与《四十二章经》译事则含东晋南北朝僧传层累附会成分。",
