          "detail": "永平十二年春正月，滇西澜沧江以西之哀牢王柳貌遣子率种人内属，其称邑王者七十七人、户五万一千八百九十、口五十五万三千七百一十一；汉明帝遂割益州郡西部都尉所领六县合哀牢地正式设立“永昌郡”（治不韦县，今云南保山东北），置哀牢、博南二县，始通博南山（兰津渡澜沧江）西南丝绸古道。",
