          "detail": "自汉平帝时河汴决坏，河水东南夺汴入淮泛滥兖豫六十余年。永平十二年夏四月，汉明帝遣水利专家王景与将作谒者王吴发卒数十万修渠筑堤：自荥阳东至千乘海口千余里，王景商度地势，凿山阜、破砥绩、直截沟涧、防遏冲要、疏决壅积，十里立一水门令河汴水势更相洄注无复溃漏之患。历时一年耗资百亿，永平十三年夏工程告竣，明帝亲巡行河汴，河汴分流复其旧迹，此后直至唐末五代近八百年间黄河下游未发生重大改道。",
