          "detail": "永平十六年二月，东汉改变建武以来北疆纯守态势，发四路北征北匈奴：祭彤、吴棠出高阙，来苗、文穆出平城，耿秉、秦彭出居延，唯奉车都尉窦固与耿忠率万二千骑出酒泉塞至天山（祁连山），击破呼衍王斩首千余级，追至蒲类海（今新疆巴里坤湖），攻占丝路咽喉伊吾卢地（今新疆哈密），置宜禾都尉留吏士屯田。窦固随即遣早年为人佣书投笔叹曰“大丈夫无它志略，犹当效傅介子、张骞立功异域以取封侯，安能久事笔砚间乎”之假司马班超，率从事郭恂及吏士三十六人出使西域。初至鄯善，鄯善王广礼敬甚备，俄因北匈奴使者百余人抵城而骤然疏懈；班超断知必有虏使，召三十六吏士激昂誓师：“不入虎穴，焉得虎子！当今之计，独有因夜以火攻虏，使彼不知我多少，必大震怖，可殄尽也。”夜半顺奔风纵火鼓噪袭匈奴营，超手格杀三人，吏兵斩其使及从士三十余级、余百许人悉烧死；明日持虏使首级示鄯善王广，一国震怖纳子为质，继而又降服南道大国于阗与北道西端疏勒，新莽以来断绝六十五年之西域再度归汉。",
