          "detail": "永平十八年八月壬戌汉明帝崩，太子刘炟即位（汉章帝）。北匈奴乘汉大丧，遣左鹿蠡王二万骑击破车师杀后王安得，围攻杀害西域都护陈睦，继以重兵围困戊校尉耿恭数百汉军于傍涧山城“疏勒城”（车师后部坚塞，今新疆奇台半截沟石城子遗址，2014—2019年考古发掘出土大量汉代板瓦筒瓦及五铢钱确证）。匈奴于山涧下壅绝水源，耿恭于城中穿井十五丈不得水，吏士渴乏至笮马粪汁而饮；恭仰天叹息整衣服向井再拜为吏士祷，有顷水泉奔出，扬水示虏虏以为神引去。未几焉耆、龟兹攻没都护，车师复叛与匈奴共围耿恭，食尽穷困，耿恭与士卒推诚同死生，煮铠弩食其筋革，无一人有二心，诱匈奴招降使上城手击杀之炙诸城上。苦守逾年至建初元年（76年）正月，酒泉太守段彭与秦彭、王蒙、皇甫援发七千军西救，范羌率二千人冒丈余深雪分兵迎耿恭突围，边战边行，三月抵玉门关时仅余十三人生还，衣屦穿决、形容枯槁，中郎将郑众亲为恭及吏士沐浴上疏请赏，举朝感泣，拜恭骑都尉。",
