          "title": "汉章帝召开洛阳“白虎观会议”讲议五经同异，班固撰集《白虎通义》法典化三纲六纪",
          "detail": "建初四年冬十一月壬戌，汉章帝采纳校书郎杨终与太常楼望建议，下诏太常、将、大夫、博士、议郎、郎官及诸生、诸王会集洛阳北宫白虎观，就今古文经学《五经》同异展开数月御前大讨论：使五官中郎将魏应承制问，侍中淳于恭奏，汉章帝效法汉宣帝石渠阁故事亲自称制临决，包括贾逵（古文经代表）、丁鸿、楼望、桓郁、班固等名儒悉数与会。会后命兰台令史班固撰集奏议编成《白虎通德论》（通称《白虎通义》四卷），以今文经学融合阴阳五行谶纬，将“三纲”（君为臣纲、父为子纲、夫为妻纲）与“六纪”正式确立为帝国钦定政治伦理教条。",
