          "title": "兰台令史班固历二十余载撰成中国首部纪传体断代正史《汉书》主体（妹班昭续成八表天文志）",
          "detail": "扶风安陵史学家班彪曾作《史记后传》六十五篇未竟而卒；子班固居家续纂，永平中遭人告发私改国史下京兆狱，弟班超驰诣阙上书讼冤，汉明帝召见奇其才，除兰台令史、迁校书郎，敕令利用皇家秘府档案专著汉史。自永平中至章帝建初年间（约公元82年前后）历二十余年，班固基本修成起自汉高祖元年、终于王莽地皇四年共二百三十年西汉全史——《汉书》（十二帝纪、八表、十志、七十列传共百篇八十余万字；其中八表及《天文志》未成稿，92年班固死窦宪狱后，汉和帝特诏其博学之妹曹大家班昭就东观藏书阁踵成八表、马续续成《天文志》）。《汉书》首创“包举一代”之纪传体断代史体例，增设《刑法志》《食货志》《地理志》《艺文志》，为此后历朝二十四史确立标准正史范式。",
