          "title": "汝南许慎遣子许冲献《说文解字》十五卷，奠定中国传统文字学（“小学”）千古基石",
          "detail": "建光元年（三月邓太后崩汉安帝亲政，蔡伦受诬饮药卒）九月己卯，病居故里的“五经无双”经学大师汝南召陵人许慎（字叔重），遣子许冲诣阙奏献自和帝永元十二年（100年）起历二十二载编纂修订而成之字典巨著《说文解字》十五卷。全书针对俗儒鄙夫玩其所习、妄说字义之弊，首创五百四十部首检字法，收录小篆正文九千三百五十三字、古文籀文等重文一千一百六十三字，系统确立象形、指事、会意、形声、转注、假借“六书”汉字构形理论，保存海量先秦古文字形音义，成为后世识读甲骨金文简帛与训诂治经之总锁钥。",
          "category": "思想与文化",
          "regionId": "zhongyuan",
          "source": "《后汉书·儒林列传下》（许慎传）；许冲《上〈说文解字〉表》（附《说文解字》卷十五下）",
