          "title": "班超少子班勇拜西域长史率五百兵出屯柳中，完成东汉对西域“三绝三通”",
          "detail": "自永初元年罢都护后，北匈奴挟车师屡犯敦煌河西，元初六年索班屯伊吾复为匈奴攻杀。朝议多主闭玉门、阳关彻底放弃西域，唯班超少子班勇于公卿廷议上慷慨力争：若弃西域资匈奴，则虏钞暴日增，河西城门必昼闭！延光二年夏，汉安帝采纳班勇方略，拜班勇为西域长史，将弛刑士五百人西出屯柳中（今新疆鄯善鲁克沁）。延光三年至顺帝永建二年（124—127），班勇连破匈奴伊蠡王与呼衍王、斩车师后王军就，西域城郭诸国再度归附东汉（史称汉通西域“三绝三通”），班勇并据亲历撰成《西域记》（为《后汉书·西域传》所本）。",
