          "detail": "延光四年三月汉安帝南巡崩于宛至叶县道中，阎皇后与兄车骑将军阎显恐被其谗废为济阴王之皇太子刘保继位问罪，秘不发丧驰归洛阳，迎立章帝孙幼弱之北乡侯刘懿即位。十月北乡侯在位仅七月病薨，阎显再度秘丧闭宫门，欲再征诸王子以久握朝柄。十一月丁巳夜，中黄门孙程、王康、王国等十九名宦官聚谋，斩省门夺权奸党江京、刘安，迎年仅十一岁的废太子济阴王刘保于德阳殿西钟下即皇帝位（汉顺帝），收捕诛杀阎显兄弟、迁阎太后于离宫。孙程等十九名宦官论功尽封列侯（世称“十九侯”），顺帝继于阳嘉四年（135）破例准许宦官养子袭爵，宦官世袭勋贵集团正式坐大。",
