          "title": "太史令张衡创制世界最早测震仪“候风地动仪”，于洛阳灵台实测验知陇西地震",
          "detail": "阳嘉元年秋七月，博通天文历算与辞赋之太史令南阳西鄂人张衡（此前已研制水力齿轮传动之漏水转浑天仪并撰宇宙论巨著《灵宪》），针对东汉地震频发，以精铜铸成世界科技史上第一台验震仪器——“候风地动仪”：员径八尺，合盖隆起形似酒尊，中有都柱（惯性摆），傍行八道，施关发机，外有八龙首衔铜丸，下有蟾蜍张口承之，如有地动尊则振龙机发吐丸而蟾蜍衔之，振声激扬，寻其方面乃知震之所在，验之以事合契若神。尝有一龙机发而京师地不觉动，洛阳学者咸怪其无征，数日后驿使果驰报陇西发生地震（如永和三年138年二月乙亥京师及金城陇西大地震），于是皆服其妙，自此令史官记地动所从方起。",
          "category": "科技与文化",
          "regionId": "zhongyuan",
