          "title": "汉顺帝遣杜乔、张纲等“八使”分行州郡纠贪，张纲埋轮洛阳都亭直劾大将军梁冀",
          "detail": "汉安元年秋八月丁卯，汉顺帝感朝政日敝，特选光禄大夫杜乔、周举、郭遵、冯羡、栾巴、侍御史张纲、周栩、刘班共八人（号“八俊/八使”）分行全国州郡，表扬贤良、纠举贪污（刺史二千石有臧罪者驿马上报，墨绶县令以下便辄收举）。七使皆奉命就道，唯侍御史广陵张纲最年少官微，出宫行至洛阳都亭，当场将使车车轮拆埋地下，凛然叹曰：“豺狼当路，安问狐狸！”遂投书阙下，历数当朝外戚大将军梁冀（顺帝梁皇后之兄，父梁商卒后继任大将军）及其弟河南尹梁不疑肆行贪残、陷害忠良十五大无君罪状，京师震动。顺帝知纲言直而受制梁氏戚畹不能问罪；梁冀恨纲入骨，故意出张纲为暴乱方炽之广陵太守欲借贼手杀之，不料张纲单车径诣张婴万余义军营门晓以利害，张婴感泣率部归降散归田里。",
