          "detail": "熹平四年春三月，议郎陈留蔡邕与五官中郎将堂溪典、光禄大夫杨赐、谏议大夫马日磾、议郎张驯、韩说、太史令单飏等，鉴于经籍去圣久远、文字多谬，俗儒穿凿行贿兰台漆书经字以合私学，联名奏求正定《六经》文字。汉灵帝诏许，由当世辞章书法大家蔡邕亲自以端庄典雅之标准“八分”汉隶蘸朱砂书丹于碑，命工匠镌刻立于洛阳南郊太学讲堂门外（历九年至光和六年183年完工，刻成《周易》《尚书》《鲁诗》《仪礼》《春秋》《公羊传》《论语》七经共四十六碑，逾二十万字）。石经既立，成为天下学子校勘经本之国家法定标准本，四方儒生争来观视及摹写（开启碑刻传拓先声），“其观视及摹写者，车乘日千余辆，填塞街陌”，史称《熹平石经》（又称“一字石经”）。",
