          "detail": "光和元年二月己未，汉灵帝于洛阳宫城鸿都门创设“鸿都门学”，不经儒门太学与州郡察举，专召能为尺牍、辞赋及善书鸟篆者相课试至千人，出为刺史太守入为尚书侍中（虽遭儒臣蔡邕、阳球痛斥为小人弄文，客观上却成为中国乃至世界最早之文学书画专科艺术学院）。同年灵帝贪敛私财，竟在西园开立卖官交易所公开标价：二千石官两千万钱，四百石四百万钱，依官职肥瘠与求官者德次讨价还价（有德望者半价或十之二三），富者先交钱、贫者到任后加倍搜刮偿纳，甚至司徒、太尉三公高位亦明码标价五百万至一千万钱（崔烈因程夫人入钱五百万为司徒，时论铜臭），东汉官僚体系彻底腐败崩解。",
