          "detail": "中平五年春，太常江夏人刘焉见王室多故，向灵帝建言“四方兵寇，由刺史威轻，既不能禁，且用非其人所致，宜改置牧伯，选清名重臣以居其任”。朝廷遂改重点州部之六百石监察刺史为秩二千石、统掌一州军民财赋生杀大权之“州牧”（以宗室刘焉为益州牧、刘虞为幽州牧、黄琬为豫州牧）。自汉武帝元封五年（前106）确立之“刺史以卑临尊监察郡国”体制彻底转变为州—郡—县三级行政军事制，州牧跨郡拥兵自重，直接催生汉末群雄割据。",
