          "title": "灵帝崩，何进召董卓入洛被宦官诱杀，袁绍尽诛宫中宦官，董卓废少帝立九岁汉献帝专横乱政",
          "detail": "中平六年四月丙辰汉灵帝崩，十四岁皇子刘辩（汉少帝）即位，何太后临朝，大将军何进与司隶校尉袁绍密谋借外兵胁迫太后诛灭中常侍张让、段珪等十常侍宦官集团，不顾曹操“一狱吏足矣，何必纷纷召外兵”及郑泰、卢植力谏，私召驻河东之并州牧凉州军阀董卓勒兵向京师。八月戊辰张让等先发制人，矫太后诏召何进入嘉德殿前斩之；袁绍、袁术、曹操遂引兵攻入南北宫阙，捕杀宦官无少长二千余人（或无须青年误死者甚众），外戚与宦官百年死斗同归于尽。董卓趁洛阳权力真空率西凉兵入京吞并何进、丁原部曲（诱吕布杀丁原），九月甲戌于崇德前殿蛮横废少帝刘辩为弘农王（次年鸩杀），改立九岁陈留王刘协为帝（汉献帝），董卓自拜相国赞拜不名、剑履上殿，纵胡汉乱兵奸略洛阳贵戚民庶，东汉中枢彻底崩塌。",
