          "detail": "初平元年春正月，后将军袁术、冀州牧韩馥、豫州刺史孔伷、兖州刺史刘岱、河内太守王匡、勃海太守袁绍、陈留太守张邈、奋武将军曹操等关东牧守同时起兵众各数万讨伐董卓，共推四世三公门第之袁绍为盟主。董卓畏关东兵锋（孙坚于阳人、梁东破卓军，曹操于汴水力战负伤），不顾朝臣杨彪等反对，于二月丁亥强挟汉献帝西迁长安，驱赶洛阳数百万吏民徒步西行（道途饥蹙相蹈藉死者盈路），命吕布发掘东汉诸帝陵寝及公卿冢墓尽取金宝，纵火彻底焚烧洛阳南北宫、宗庙、府库、民居及兰台东观所藏图书秘籍（辟雍、石经亦遭兵燹），二百里内化为焦土无复鸡犬，东汉经营百六十余年之东都洛阳毁于一旦。关东诸将随即各怀异心互相吞并，天下陷入全面军阀混战。",
