          "title": "司徒王允联吕布诛杀董卓，旋遭李傕、郭汜反扑陷长安；曹操收编三十万精锐“青州兵”",
          "detail": "初平三年四月辛巳，司徒王允与士孙瑞结纳董卓亲信勇将吕布为内应，趁汉献帝疾愈大会未央殿，伏兵北掖门由吕布持矛刺杀太师董卓并夷其三族，长安士民歌舞于道。然王允刚愎拒赦凉州部曲，董卓旧将李傕、郭汜、樊稠、张济采谋士贾诩“奉国家以征天下”求生毒计，沿途收兵十余万反扑围攻长安；六月戊午城陷，吕布败奔关东，王允不肯逃离蒙难，三辅百姓遭凉州乱兵屠掠殆尽，谷一斛值五十万钱人相食。同年冬，东郡太守曹操领兖州牧，于寿张、济北追击破降青州黄巾百万之众（男女百余万口），收其精锐卒三十余万编为“青州兵”，奠定曹氏霸业基干武力。",
