          "title": "曹操迎汉献帝迁都许县（“奉天子以令不臣”），采枣祗、韩浩议大兴“许下屯田”",
          "detail": "汉献帝自长安乘乱东逃回残破洛阳，宫室烧尽百官披荆棘依墙壁采野藿断粮。建安元年秋八月，兖州牧曹操采纳谋士毛玠、荀彧“奉天子以令不臣，修耕植以畜军资”之远略，亲率师入洛阳朝献帝，随即迎奉天子迁都颍川许县（史称许都），改元建安，曹操自领司隶校尉、录尚书事、司空行车骑将军，在群雄逐鹿中牢牢掌握代表汉室正统之政治主动权。同年鉴于战乱遍地荒芜、袁绍军仰食桑椹袁术兵取给蒲蠃之饥困，曹操采枣祗、韩浩首倡，募流民于许下创办大规模官营民屯（任峻为典农中郎将，各郡国置典农校尉、屯田都尉，不隶郡县直属司空府；计牛输谷：持官牛者官得六分民得四分，私牛者与官中分），当年即收获谷百万斛，“数年中所在积粟，仓廪皆满”，曹操征伐四方无复运粮之劳，遂成兼并群雄之经济柱石。",
